H,W=12,19
def cast(seed):
    r,c=seed
    cands={}
    cands['down']=[(rr,c) for rr in range(r+1,11)]
    cands['up']=[(rr,c) for rr in range(1,r)]
    cands['left']=[(r,cc) for cc in range(1,c)]
    cands['right']=[(r,cc) for cc in range(c+1,W-1)]
    cands['d_downleft']=[(r+k,c-k) for k in range(1,12) if 0<r+k<11 and 0<=c-k<W]
    cands['d_downright']=[(r+k,c+k) for k in range(1,12) if 0<r+k<11 and c+k<W]
    cands['d_upleft']=[(r-k,c-k) for k in range(1,12) if 0<r-k and 0<=c-k]
    cands['d_upright']=[(r-k,c+k) for k in range(1,12) if 0<r-k and c+k<W]
    return cands
anom=[(r,3) for r in range(1,11)]+[(r,12) for r in range(0,11)]
for name in ['down','up','left','right','d_downleft','d_downright','d_upleft','d_upright']:
    cover={cell:[] for cell in anom}
    for s in seeds:
        for cell in cast(s)[name]:
            if cell in cover: cover[cell].append(s)
    full=sum(1 for cell in anom if cover[cell])
    print(name, f"{full}/{len(anom)} anomalous cells covered", {k:v for k,v in cover.items() if not v}.__len__(),"uncovered")
